window.MORE=[
{id:"evo",t:"Evolution",c:"Science",i:"🦎",p:[["Natural selection","Evolution is change in the heritable traits of populations over generations. Charles Darwin and Alfred Russel Wallace independently proposed natural selection, and Darwin published On the Origin of Species in 1859."],["Evidence","Fossils, comparative anatomy and DNA all support common descent. Humans share roughly 98 to 99% of their DNA with chimpanzees."]],r:["dna","cell","evolution"]},
{id:"atom",t:"Atoms and the Periodic Table",c:"Science",i:"⚛️",p:[["The atom","Atoms consist of a nucleus of protons and neutrons surrounded by electrons. The number of protons defines the element."],["Periodic table","Dmitri Mendeleev published his periodic table in 1869 and predicted elements not yet discovered. Today it lists 118 confirmed elements."]],r:["light","elec","periodictable"]},
{id:"grav",t:"Gravity",c:"Science",i:"🍎",p:[["Theories","Newton described gravity as a force between masses in 1687. Einstein’s general relativity (1915) describes it as the curvature of spacetime."],["Effects","Gravity holds planets in orbit and produces ocean tides. On the Moon it is about one sixth as strong as on Earth."]],r:["solar","bh"]},
{id:"cell",t:"The Cell",c:"Science",i:"🔬",p:[["Basic unit","The cell is the basic unit of life. Robert Hooke coined the word in 1665 while examining cork under a microscope."],["Types","Bacteria have no nucleus, while plant and animal cells do. An adult human body contains tens of trillions of cells."]],r:["dna","evo"]},
{id:"light",t:"Light and the Spectrum",c:"Science",i:"🌈",p:[["Speed","Light travels at about 299,792 km per second in a vacuum and behaves as both a wave and a stream of photons."],["Spectrum","Visible light is a narrow band of the electromagnetic spectrum, between infrared and ultraviolet. A prism splits white light into colors from red to violet."]],r:["atom","elec"]},
{id:"ww2",t:"World War II",c:"History",i:"🪖",p:[["Course","The war ran from 1939 to 1945 and involved most of the world’s nations, divided between the Allies and the Axis. It began with Germany’s invasion of Poland."],["Outcome","Germany surrendered in May 1945 and Japan in September 1945. The United Nations was founded in 1945, and the war is estimated to have killed 70 to 85 million people. Germany occupied most of Europe, and Japan much of East and Southeast Asia."]],r:["space","indrev"]},
{id:"renais",t:"The Renaissance",c:"History",i:"🎨",p:[["Rebirth","A cultural movement that began in Italy in the 14th century and spread across Europe, reviving interest in classical learning and art."],["Figures","Leonardo da Vinci, Michelangelo and Raphael produced masterpieces, while Gutenberg’s printing press spread new ideas quickly."]],r:["print","rome"]},
{id:"maya",t:"The Maya",c:"History",i:"🗿",p:[["Cities","The Maya civilization flourished in Mesoamerica, with its Classic period peaking between about 250 and 900 CE in cities such as Tikal and Palenque."],["Achievements","They developed a hieroglyphic writing system, advanced astronomy and an intricate calendar. Millions of Maya people live in Guatemala and Mexico today."]],r:["egypt","silk"]},
{id:"silk",t:"The Silk Road",c:"History",i:"🐪",p:[["Routes","A network of trade routes linking China with the Mediterranean from around the 2nd century BCE. Silk, spices and paper moved west, while goods and ideas moved in both directions."],["Impact","Religions, technologies and diseases also traveled along it. Sea routes gradually replaced much of the overland trade."]],r:["rome","sahara"]},
{id:"space",t:"The Space Race",c:"History",i:"🚀",p:[["Rivalry","A Cold War contest between the United States and the Soviet Union. The Soviets launched Sputnik 1 in 1957 and sent Yuri Gagarin into orbit in 1961."],["The Moon","Apollo 11 landed on the Moon on 20 July 1969, and Neil Armstrong was the first person to walk on its surface."]],r:["solar","flight"]},
{id:"everest",t:"Mount Everest",c:"Geography",i:"🏔️",p:[["Height","Earth’s highest mountain above sea level, at about 8,849 m, on the border of Nepal and Tibet. Tenzing Norgay and Edmund Hillary made the first confirmed ascent in 1953."],["Growth","It is still rising by a few millimeters a year as the Indian Plate pushes into Eurasia."]],r:["tect","antarc"]},
{id:"sahara",t:"The Sahara",c:"Geography",i:"🏜️",p:[["Size","The largest hot desert on Earth, covering about 9 million km² of North Africa, roughly the size of the United States."],["Terrain","Only a fraction is sand dunes. Most is rock and gravel, and several thousand years ago parts of it were green and well watered."]],r:["nile","tect"]},
{id:"pacific",t:"The Pacific Ocean",c:"Geography",i:"🌊",p:[["Scale","The largest and deepest ocean, covering about a third of the planet. The Mariana Trench holds its deepest point, nearly 11,000 m down."],["Ring of Fire","The belt of volcanoes and earthquake zones around its edge contains about 75% of the world’s active volcanoes."]],r:["ph","tect"]},
{id:"nile",t:"The Nile",c:"Geography",i:"🛶",p:[["Length","At about 6,650 km it is traditionally counted as the longest river in the world, and its basin spans eleven countries before it reaches the Mediterranean."],["Role","Its annual floods made Egyptian agriculture possible. The Aswan High Dam, completed in 1970, now controls the flow."]],r:["egypt","sahara"]},
{id:"antarc",t:"Antarctica",c:"Geography",i:"🐧",p:[["Extremes","The southern continent is the coldest, driest and windiest on Earth. Its ice sheet holds about 70% of the world’s fresh water."],["Governance","No country owns it. The Antarctic Treaty of 1959 reserves it for peaceful scientific work."]],r:["pacific","everest"]},
{id:"comp",t:"The Computer",c:"Technology",i:"💻",p:[["Early machines","Charles Babbage designed the Analytical Engine in the 1830s, and ENIAC, completed in 1945, was among the first electronic general-purpose computers."],["Miniaturization","The transistor, invented in 1947, and the integrated circuit made computers small and cheap. Modern chips hold billions of transistors."]],r:["internet","elec"]},
{id:"print",t:"The Printing Press",c:"Technology",i:"📜",p:[["Invention","Johannes Gutenberg developed movable-type printing in Germany around 1450. His Bible was among the first major books printed in Europe."],["Impact","Books became cheaper and literacy rose, and ideas of the Renaissance, the Reformation and science spread quickly."]],r:["renais","internet"]},
{id:"flight",t:"Flight",c:"Technology",i:"✈️",p:[["First flight","The Wright brothers made the first controlled, powered airplane flight on 17 December 1903 at Kitty Hawk, North Carolina."],["Jet age","Commercial jet service began in the 1950s, and Concorde carried passengers at more than twice the speed of sound from 1976 to 2003."]],r:["space","indrev"]},
{id:"renew",t:"Renewable Energy",c:"Technology",i:"🌞",p:[["Sources","Sunlight, wind, water and geothermal heat are replenished naturally. Solar panels turn light directly into electricity using the photovoltaic effect."],["Challenges","Wind and solar output varies with the weather, so grids need storage, flexible generation and strong transmission. Countries such as Iceland and Kenya also tap steady geothermal heat."]],r:["elec","photo"]},
{id:"gps",t:"GPS",c:"Technology",i:"📡",p:[["How it works","The Global Positioning System uses a constellation of satellites that broadcast time signals. A receiver needs signals from at least four of them to fix its position."],["Accuracy","Each satellite carries an atomic clock, and relativity corrections keep it accurate. Phones are typically accurate to within a few meters outdoors."]],r:["space","comp"]}];

;
/* data/articles-science.js */
window.MORE=(window.MORE||[]).concat([
{id:"quantum",t:"Quantum Mechanics",c:"Science",i:"🌀",p:[["Origins","Max Planck proposed in 1900 that energy is emitted in discrete packets called quanta, and Einstein used the idea in 1905 to explain the photoelectric effect."],["Core ideas","Particles also behave as waves, and Heisenberg’s uncertainty principle (1927) says position and momentum cannot both be known exactly. Superposition lets a quantum system exist in a combination of states until it is measured."],["Applications","Transistors, lasers, MRI scanners and atomic clocks all rely on quantum physics. Quantum computers use qubits, which can hold superpositions of 0 and 1."]],r:["atom","light"]},
{id:"relat",t:"Relativity",c:"Science",i:"⏳",p:[["Special relativity","Einstein’s 1905 theory rests on two ideas: the laws of physics are the same for all observers in uniform motion, and the speed of light is constant. It implies time dilation and the equivalence of mass and energy, E = mc²."],["General relativity","Published in 1915, it treats gravity as the curvature of spacetime. It predicted that light bends around massive objects, confirmed during the 1919 solar eclipse."],["Tests","It also predicts gravitational waves, first detected directly by LIGO in 2015, and GPS satellites must correct for relativistic time effects to stay accurate."]],r:["grav","gps"]},
{id:"brain",t:"The Human Brain",c:"Science",i:"🧠",p:[["Structure","The adult brain weighs about 1.4 kg and contains roughly 86 billion neurons. Its main parts are the cerebrum, the cerebellum and the brainstem."],["Signals","Neurons communicate through electrical impulses and chemical messengers called neurotransmitters, passed across junctions known as synapses."],["Energy and sleep","The brain uses about 20% of the body’s energy while making up about 2% of its weight. Sleep helps consolidate memories."]],r:["cell","evo"]},
{id:"immune",t:"The Immune System",c:"Science",i:"🛡️",p:[["First defenses","The skin and mucous membranes form the first barrier. Inside the body, white blood cells such as neutrophils and macrophages attack invaders."],["Adaptive immunity","T cells and B cells remember specific pathogens, and B cells make antibodies. This memory is why you rarely catch some diseases twice."],["Vaccines","Vaccines train adaptive immunity without causing the disease. Edward Jenner’s smallpox vaccine of 1796 was the first, and smallpox was declared eradicated in 1980."]],r:["cell","dna"]},
{id:"climate",t:"Climate and Weather",c:"Science",i:"🌦️",p:[["The difference","Weather describes short-term atmospheric conditions, while climate is the average over decades. Climate zones range from tropical to polar."],["Greenhouse effect","Gases such as carbon dioxide and methane trap heat, keeping Earth about 33°C warmer than it would be without an atmosphere. Carbon dioxide has risen from about 280 ppm before industrialization to over 420 ppm."],["Trend","Major climate agencies estimate that global average temperature has risen by roughly 1.1 to 1.2°C since the late 1800s."]],r:["renew","pacific"]},
{id:"sound",t:"Sound",c:"Science",i:"🔊",p:[["Waves","Sound is a mechanical wave that needs a medium. In air at 20°C it travels at about 343 m/s, and it moves faster in water and solids."],["Pitch and loudness","Frequency sets pitch and amplitude sets loudness. Humans hear roughly 20 Hz to 20 kHz."],["Uses","Sonar and ultrasound imaging use reflected sound. A sonic boom is the shock wave from an object moving faster than sound."]],r:["light","flight"]},
{id:"magnet",t:"Magnetism",c:"Science",i:"🧲",p:[["Fields","Magnets have north and south poles, with a magnetic field around them. Moving charges create magnetic fields, which links magnetism to electricity."],["Earth’s field","Earth’s magnetic field, generated by molten iron in the outer core, shields the planet from the solar wind and produces auroras at high latitudes."],["Induction","Michael Faraday showed in 1831 that a changing magnetic field induces an electric current, the principle behind generators and transformers."]],r:["elec","tect"]},
{id:"stars",t:"Stars and Galaxies",c:"Science",i:"⭐",p:[["Life of a star","Stars shine by fusing hydrogen into helium. The Sun is roughly halfway through a main-sequence life of about 10 billion years."],["Death of a star","Massive stars end as supernovae, leaving neutron stars or black holes, while Sun-like stars become white dwarfs."],["Galaxies","The Milky Way contains hundreds of billions of stars. The Andromeda Galaxy, about 2.5 million light-years away, is the nearest large galaxy."]],r:["solar","bh"]}]);

;
/* data/articles-history.js */
window.MORE=(window.MORE||[]).concat([
{id:"greece",t:"Ancient Greece",c:"History",i:"🏺",p:[["City-states","Greece was a world of independent city-states such as Athens and Sparta. Athens developed an early form of democracy around 508 BCE under Cleisthenes."],["Culture","Socrates, Plato and Aristotle shaped Western philosophy, and the first recorded Olympic Games were held in 776 BCE."],["Conquest","Alexander the Great of Macedon conquered the Persian Empire by 330 BCE and spread Greek culture across the Middle East. Rome took control of Greece in 146 BCE."]],r:["rome","renais"]},
{id:"mongol",t:"The Mongol Empire",c:"History",i:"🐎",p:[["Rise","Genghis Khan united the Mongol tribes in 1206. Within decades the empire stretched from Korea to Eastern Europe."],["Scale","At its peak it was the largest contiguous land empire in history, covering roughly 24 million km²."],["Legacy","The Pax Mongolica protected trade along the Silk Road, and Kublai Khan founded China’s Yuan dynasty in 1271."]],r:["silk","rome"]},
{id:"frrev",t:"The French Revolution",c:"History",i:"🇫🇷",p:[["Outbreak","The revolution began in 1789 amid financial crisis and unrest, and the Bastille fell on 14 July of that year."],["Radical phase","The monarchy was abolished in 1792, Louis XVI was executed in 1793, and the Reign of Terror followed."],["Outcome","Napoleon took power in 1799. The Declaration of the Rights of Man and of the Citizen and the Napoleonic Code influenced law across Europe."]],r:["renais","indrev"]},
{id:"wwi",t:"World War I",c:"History",i:"🎖️",p:[["Spark","The war ran from 1914 to 1918 and was triggered by the assassination of Archduke Franz Ferdinand in Sarajevo on 28 June 1914."],["Trenches","Trench warfare on the Western Front caused enormous casualties. Machine guns, tanks and poison gas changed the battlefield."],["Aftermath","The armistice took effect on 11 November 1918, and the Treaty of Versailles followed in 1919. The war killed roughly 20 million people, military and civilian."]],r:["ww2","indrev"]},
{id:"phrev",t:"The Philippine Revolution",c:"History",i:"🇵🇭",p:[["Uprising","The Katipunan, founded by Andrés Bonifacio in 1892, launched the revolt against Spanish rule in August 1896. José Rizal was executed on 30 December 1896 and became a national martyr."],["Independence","Emilio Aguinaldo declared independence on 12 June 1898 at Kawit, Cavite."],["Aftermath","Spain ceded the Philippines to the United States under the 1898 Treaty of Paris, which led to the Philippine–American War. Full independence from the United States came on 4 July 1946."]],r:["ph","ww2"]},
{id:"coldwar",t:"The Cold War",c:"History",i:"🧊",p:[["Rivalry","After World War II the United States and the Soviet Union competed for influence without fighting each other directly, from about 1947 to 1991."],["Flashpoints","Crises included the Berlin Blockade, the Korean War, the Cuban Missile Crisis of 1962 and the Vietnam War."],["End","The Berlin Wall fell on 9 November 1989, and the Soviet Union dissolved in December 1991."]],r:["space","ww2"]}]);

;
/* data/articles-geography.js */
window.MORE=(window.MORE||[]).concat([
{id:"reef",t:"The Great Barrier Reef",c:"Geography",i:"🐠",p:[["Size","Off the coast of Queensland, Australia, it stretches about 2,300 km and is made up of nearly 3,000 individual reefs."],["Life","It is built by tiny coral polyps and shelters around 1,500 species of fish."],["Threats","Mass bleaching events, driven by warming seas, have struck repeatedly since 1998."]],r:["pacific","climate"]},
{id:"arctic",t:"The Arctic",c:"Geography",i:"🐻‍❄️",p:[["The ocean","The Arctic Ocean is the smallest and shallowest ocean, mostly covered by sea ice that has been shrinking in recent decades."],["People and wildlife","Indigenous peoples such as the Inuit have lived there for thousands of years, and polar bears hunt on the sea ice."],["Change","The region is warming several times faster than the global average."]],r:["antarc","climate"]},
{id:"volc",t:"Volcanoes",c:"Geography",i:"🌋",p:[["Formation","Magma rises through the crust at plate boundaries and hot spots. More than 1,000 volcanoes on land are considered potentially active."],["Great eruptions","Tambora in 1815 caused the 1816 “Year Without a Summer”, and Krakatoa’s 1883 eruption was heard thousands of kilometers away."],["Benefits","Volcanic soils are fertile, and volcanic regions can supply geothermal energy."]],r:["tect","ph"]},
{id:"himal",t:"The Himalayas",c:"Geography",i:"⛰️",p:[["Range","About 2,400 km long, the range crosses Bhutan, India, Nepal, China and Pakistan. Ten of the world’s fourteen peaks above 8,000 m stand in it."],["Water","Its glaciers feed the Indus, Ganges and Brahmaputra rivers, which support hundreds of millions of people."],["Formation","Uplift began roughly 50 million years ago when the Indian Plate collided with Eurasia."]],r:["everest","tect"]},
{id:"med",t:"The Mediterranean Sea",c:"Geography",i:"⛵",p:[["Geography","An almost enclosed sea between Europe, Africa and Asia, linked to the Atlantic by the Strait of Gibraltar and to the Red Sea by the Suez Canal."],["History","It was the cradle of the Phoenician, Greek and Roman civilizations."],["Climate","Hot, dry summers and mild, wet winters define the Mediterranean climate, which also occurs in California, central Chile, South Africa and southern Australia."]],r:["rome","egypt"]},
{id:"quake",t:"Earthquakes",c:"Geography",i:"📉",p:[["Cause","Earthquakes occur when stress built up along faults is suddenly released, sending seismic waves outward from the focus."],["Measuring","The Richter scale appeared in 1935, and scientists now use the moment magnitude scale. Each whole step up represents about 32 times more energy."],["Largest","The 1960 Valdivia earthquake in Chile, at magnitude 9.5, is the strongest ever recorded."]],r:["tect","ph"]}]);

;
/* data/articles-technology.js */
window.MORE=(window.MORE||[]).concat([
{id:"ai",t:"Artificial Intelligence",c:"Technology",i:"🤖",p:[["Origins","The field was named at the Dartmouth workshop in 1956."],["Machine learning","Modern systems learn patterns from data instead of following hand-written rules. Deep neural networks produced breakthroughs in image recognition after 2012."],["Uses and concerns","AI is used in translation, medicine and navigation, and it raises questions about bias, privacy and jobs."]],r:["comp","internet"]},
{id:"battery",t:"Batteries",c:"Technology",i:"🔋",p:[["Basics","A battery converts chemical energy into electrical energy. Alessandro Volta built the first, the voltaic pile, in 1800."],["Lithium-ion","Sony commercialized the lithium-ion battery in 1991, and Goodenough, Whittingham and Yoshino shared the 2019 Nobel Prize in Chemistry for developing it."],["Grid role","Large batteries store solar and wind power and help balance supply and demand on the grid."]],r:["renew","elec"]},
{id:"nuclear",t:"Nuclear Power",c:"Technology",i:"☢️",p:[["Fission","Splitting heavy atoms such as uranium-235 releases heat, which makes steam to drive turbines."],["History","The first controlled reactor, Chicago Pile-1, started in December 1942, and commercial plants began operating in the 1950s."],["Debate","Nuclear supplies roughly 9% of the world’s electricity with low carbon emissions, but waste, accidents such as Chernobyl in 1986 and Fukushima in 2011, and high construction costs fuel debate."]],r:["atom","elec"]},
{id:"rail",t:"Railways",c:"Technology",i:"🚆",p:[["Steam","Richard Trevithick ran the first steam locomotive in 1804, and the Liverpool and Manchester Railway opened in 1830 as the first intercity line run entirely by steam."],["Speed","Japan’s Shinkansen opened in 1964 as the first high-speed line, and modern trains run at 300 km/h or more."],["Impact","Railways standardized time zones and opened whole continents to trade."]],r:["indrev","flight"]},
{id:"phone",t:"The Telephone",c:"Technology",i:"☎️",p:[["Invention","Alexander Graham Bell received the first US telephone patent in 1876."],["Mobile","Martin Cooper of Motorola made the first handheld mobile call in 1973, and the iPhone, launched in 2007, popularized the smartphone."],["Networks","Mobile networks have moved from 1G to 5G, and most of the world’s population now uses a mobile phone."]],r:["internet","comp"]},
{id:"sat",t:"Satellites",c:"Technology",i:"🛰️",p:[["First launches","Sputnik 1 went up in 1957, followed by the American Explorer 1 in 1958."],["Orbits","Low Earth orbit sits a few hundred kilometers up, while geostationary satellites orbit at about 35,786 km above the equator and match Earth’s rotation."],["Uses","Satellites carry communications, weather forecasting, navigation and Earth observation."]],r:["space","gps"]}]);

;
/* data/articles-science2.js */
window.MORE=(window.MORE||[]).concat([
{id:"wcycle",t:"The Water Cycle",c:"Science",i:"💧",p:[["Stages","Water evaporates from oceans and land, condenses into clouds, falls as rain or snow, and flows back to the sea. The oceans hold about 97% of Earth’s water."],["Fresh water","Only about 3% of Earth’s water is fresh, and most of that is locked in ice sheets and glaciers."],["Transpiration","Plants release water vapor through their leaves, adding moisture to the air."]],r:["pacific","climate"]},
{id:"newton",t:"Newton’s Laws of Motion",c:"Science",i:"🍏",p:[["First law","An object stays at rest or in uniform motion unless a net force acts on it."],["Second law","Force equals mass times acceleration, F = ma, so the same force speeds up a light object more than a heavy one."],["Third law","Every action has an equal and opposite reaction. Newton set out all three in the Principia of 1687."]],r:["grav","flight"]},
{id:"mendel",t:"Genetics and Heredity",c:"Science",i:"🌱",p:[["Pea plants","Gregor Mendel, an Augustinian friar, bred pea plants in the 1850s and 1860s and showed that traits pass on as separate units, later called genes."],["Dominant and recessive","A dominant version of a gene shows up even when only one copy is present, while a recessive version appears only when both copies match."],["Rediscovery","Mendel published in 1866, but his work was largely ignored until it was rediscovered around 1900."]],r:["dna","evo"]},
{id:"eco",t:"Ecosystems",c:"Science",i:"🦋",p:[["Community","An ecosystem is a community of living things interacting with their physical environment. Energy flows from producers such as plants to consumers and decomposers."],["Energy loss","As a rule of thumb, only about 10% of energy passes from one feeding level to the next, which is why top predators are rare."],["Biodiversity","Rainforests and coral reefs hold the greatest variety of species, and losing one species can ripple through a whole food web."]],r:["amazon","reef"]},
{id:"acid",t:"Acids and Bases",c:"Science",i:"🧪",p:[["The pH scale","The pH scale runs from 0 to 14. A value of 7 is neutral, lower values are acidic and higher values are basic."],["Everyday examples","Lemon juice has a pH of about 2, pure water is 7 and household bleach is around 12 to 13."],["Neutralization","An acid and a base react to form a salt and water, a reaction used in antacid tablets."]],r:["atom","cell"]}]);

;
/* data/articles-history2.js */
window.MORE=(window.MORE||[]).concat([
{id:"aztec",t:"The Aztec Empire",c:"History",i:"🌞",p:[["Capital","The Mexica founded Tenochtitlan in 1325 on an island in Lake Texcoco. It grew into one of the largest cities in the world."],["Empire","In 1428 Tenochtitlan joined Texcoco and Tlacopan in the Triple Alliance, which dominated central Mexico and collected tribute from many peoples."],["Fall","Hernán Cortés and his indigenous allies took Tenochtitlan in 1521, and Mexico City was built on its ruins."]],r:["maya","explor"]},
{id:"ottoman",t:"The Ottoman Empire",c:"History",i:"🕌",p:[["Rise","Founded around 1299 by Osman I, the empire captured Constantinople in 1453 under Mehmed II, ending the Byzantine Empire."],["Height","Under Suleiman the Magnificent, who ruled from 1520 to 1566, it spanned southeastern Europe, western Asia and North Africa."],["End","The empire collapsed after World War I, and the Republic of Turkey was proclaimed in 1923."]],r:["rome","wwi"]},
{id:"china",t:"Imperial China",c:"History",i:"🐉",p:[["Unification","Qin Shi Huang unified China in 221 BCE. The Han dynasty followed and lasted from 206 BCE to 220 CE."],["Inventions","Chinese inventors gave the world paper, printing, gunpowder and the compass."],["Great Wall","The wall was built and rebuilt over centuries, and most of what survives dates from the Ming dynasty (1368 to 1644). The last emperor abdicated in 1912."]],r:["silk","print"]},
{id:"explor",t:"The Age of Exploration",c:"History",i:"🧭",p:[["Portugal","Prince Henry the Navigator sponsored voyages down the African coast, and Vasco da Gama reached India by sea in 1498."],["Columbus","Christopher Columbus sailed for Spain and reached the Caribbean in 1492."],["Magellan","The expedition Ferdinand Magellan began in 1519 completed the first circumnavigation of the globe in 1522. Magellan himself was killed in the Philippines in 1521."]],r:["ph","pacific"]},
{id:"usrev",t:"The American Revolution",c:"History",i:"🗽",p:[["Declaration","The thirteen colonies adopted the Declaration of Independence on 4 July 1776, rejecting British rule."],["War","George Washington commanded the Continental Army, and Britain recognized independence in the Treaty of Paris of 1783."],["Constitution","The Constitution was written in 1787, and the Bill of Rights was ratified in 1791."]],r:["frrev","renais"]}]);

;
/* data/articles-geography2.js */
window.MORE=(window.MORE||[]).concat([
{id:"alps",t:"The Alps",c:"Geography",i:"🎿",p:[["Extent","An arc about 1,200 km long across eight countries, with Mont Blanc, at roughly 4,800 m, as its highest peak."],["Glaciers","Alpine glaciers have been shrinking for well over a century as temperatures rise."],["History","Hannibal famously crossed the Alps with his army and elephants in 218 BCE, and today the range is a major tourism region."]],r:["tect","himal"]},
{id:"andes",t:"The Andes",c:"Geography",i:"🦙",p:[["Range","The longest continental mountain range, running about 7,000 km down the west of South America. Aconcagua in Argentina, at 6,961 m, is its highest peak."],["Peoples","The Inca Empire was centered at Cusco, and Machu Picchu was built in the mid-1400s."],["Resources","The Andes are rich in copper and silver, and the potato was first domesticated there."]],r:["amazon","tect"]},
{id:"canyon",t:"The Grand Canyon",c:"Geography",i:"🏞️",p:[["Size","The Colorado River carved the canyon in Arizona. It is about 446 km long, up to 29 km wide and more than 1,800 m deep."],["Rock layers","Its walls expose nearly 2 billion years of Earth’s geologic history."],["Protection","It became a national park in 1919 and draws millions of visitors each year."]],r:["tect","nile"]},
{id:"sea",t:"Southeast Asia",c:"Geography",i:"🌴",p:[["Region","Eleven countries make up the region, including the Philippines, Indonesia, Vietnam and Thailand, along with Timor-Leste, which joined ASEAN in 2025."],["Geography","It combines a mainland section with a vast island world. Indonesia alone has more than 17,000 islands."],["Monsoon","Seasonal monsoon rains support rice farming, the staple food across much of the region."]],r:["ph","pacific"]},
{id:"iceland",t:"Iceland",c:"Geography",i:"🧊",p:[["Location","Iceland sits on the Mid-Atlantic Ridge, where the North American and Eurasian plates are slowly pulling apart."],["Energy","Nearly all its electricity and most of its heating come from hydropower and geothermal sources."],["Democracy","Its Althing, founded in 930, is among the world’s oldest parliaments."]],r:["volc","renew"]}]);

