/* data/articles-technology2.js */
window.MORE=(window.MORE||[]).concat([
{id:"laser",t:"Lasers",c:"Technology",i:"🔦",p:[["Name and invention","Laser stands for light amplification by stimulated emission of radiation. Theodore Maiman built the first working laser in 1960."],["Properties","Laser light is coherent and of a single color, so it stays tightly focused over long distances."],["Uses","Lasers carry data through optical fibers and are used in eye surgery, barcode scanners and industrial cutting."]],r:["light","internet"]},
{id:"chip",t:"Semiconductors",c:"Technology",i:"🔌",p:[["Materials","Semiconductors such as silicon conduct electricity only under certain conditions, which lets transistors act as tiny switches."],["Moore’s law","In 1965 Gordon Moore observed that the number of transistors on a chip was doubling about every two years, a pace that held for decades."],["Manufacturing","Chips are made on silicon wafers in factories called fabs, with features only a few nanometers across. Very few companies can make the most advanced ones."]],r:["comp","atom"]},
{id:"radio",t:"Radio",c:"Technology",i:"📻",p:[["Theory","James Clerk Maxwell predicted electromagnetic waves in the 1860s, and Heinrich Hertz demonstrated them in 1887."],["Marconi","Guglielmo Marconi sent a radio signal across the Atlantic in 1901."],["Today","Radio waves carry broadcasts, Wi-Fi, mobile networks and GPS signals."]],r:["light","phone"]},
{id:"steam",t:"The Steam Engine",c:"Technology",i:"🚂",p:[["Early engines","Thomas Newcomen built a working engine in 1712 to pump water from mines. James Watt’s improvements, patented in 1769, made it far more efficient."],["Applications","Steam power drove textile mills, locomotives and ships."],["Legacy","Steam turbines still power most thermal power plants, including coal, gas and nuclear stations."]],r:["indrev","rail"]},
{id:"scope",t:"Telescopes",c:"Technology",i:"🔭",p:[["Invention","Hans Lippershey applied for a telescope patent in 1608, and in 1609 and 1610 Galileo used one to discover the moons of Jupiter."],["Reflectors","Isaac Newton built the first practical reflecting telescope in 1668, using a mirror instead of a lens."],["In space","The Hubble Space Telescope launched in 1990, and the James Webb Space Telescope launched on 25 December 2021 to observe in infrared."]],r:["stars","space"]}]);

;
/* data/articles-technology3.js */
window.MORE=(window.MORE||[]).concat([
{id:"robot",t:"Robotics",c:"Technology",i:"🦾",p:[["Origins","The word robot comes from the Czech robota, meaning forced labor, and was introduced in Karel Čapek’s 1920 play R.U.R."],["Industry","Unimate, the first industrial robot, was installed at a General Motors plant in 1961 to lift hot metal parts."],["Today","Robots now assist in surgery, sort parcels in warehouses and explore Mars, where NASA’s rovers have operated since 1997."]],r:["ai","comp"]},
{id:"crypto",t:"Cryptography",c:"Technology",i:"🔐",p:[["Ancient ciphers","Julius Caesar is said to have shifted each letter of his messages by a fixed number of places, a method now called the Caesar cipher."],["Public keys","Diffie and Hellman described public-key cryptography in 1976, and the RSA algorithm followed in 1977. It lets two parties communicate securely without first sharing a secret."],["Everyday use","Cryptography protects web traffic through HTTPS, secures bank cards and keeps messaging apps private."]],r:["internet","comp"]}]);

