/* data/articles-philippines3.js */
window.MORE=(window.MORE||[]).concat([
{id:"vigan",t:"Vigan",c:"Philippines",i:"🏘️",p:[["Colonial town","Vigan, in Ilocos Sur, is one of the best-preserved Spanish colonial towns in Asia. It was listed as a UNESCO World Heritage site in 1999."],["Streets and houses","Calle Crisologo is lined with stone-and-brick ancestral houses with tile roofs, and horse-drawn carriages called calesas still carry visitors."],["Crafts","The town is known for abel Iloco weaving, burnay pottery and Vigan longganisa sausage."]],r:["spanph","manila"]},
{id:"boracay",t:"Boracay",c:"Philippines",i:"🏖️",p:[["White Beach","Boracay is a small island off Aklan, famous for White Beach, a four-kilometer stretch of fine white sand."],["Tourism boom","It grew from a backpacker haven into one of the country’s top destinations, with hotels and restaurants lining the shore."],["Rehabilitation","In 2018 the government closed the island for six months to clean up pollution and sewage, and it reopened with new limits on visitor numbers."]],r:["phbio","ph"]},
{id:"siargao",t:"Siargao",c:"Philippines",i:"🏄",p:[["Surfing island","Siargao, off the northeast coast of Mindanao, is known as the surfing capital of the Philippines, with Cloud 9 as its best-known wave."],["Landscape","The island has coconut palm forests, lagoons, rock pools and the mangroves of the Del Carmen area."],["Typhoon Odette","Super Typhoon Odette (Rai) struck in December 2021 and badly damaged the island, which has since been rebuilding."]],r:["phtyph","mindanao"]},
{id:"pinatubo",t:"Mount Pinatubo",c:"Philippines",i:"🌋",p:[["1991 eruption","After centuries of silence, Pinatubo erupted on 15 June 1991 in the second-largest volcanic eruption of the 20th century."],["Effects","Evacuations saved thousands of lives, though ash and lahars buried towns and Clark Air Base. The ash cloud reached the stratosphere."],["Global impact","Sulfur from the eruption spread around the world and cooled global temperatures by about half a degree Celsius over the next year or two."]],r:["volc","climate"]},
{id:"lapulapu",t:"Lapulapu and Mactan",c:"Philippines",i:"⚔️",p:[["The chieftain","Lapulapu was a chieftain of Mactan island, near Cebu, who refused to submit to Spanish authority."],["Battle of Mactan","On 27 April 1521 his warriors defeated Magellan’s force and killed Magellan on the beach."],["Legacy","He is honored as one of the first Filipinos to resist foreign colonizers, and the city of Lapu-Lapu bears his name."]],r:["explor","cebu"]},
{id:"bonifacio",t:"Andrés Bonifacio",c:"Philippines",i:"🔥",p:[["Early life","Andrés Bonifacio was born in Tondo, Manila, on 30 November 1863 and worked as a clerk and warehouseman after his parents died."],["Katipunan","In 1892 he co-founded the Katipunan, a secret society that aimed to win independence from Spain by force, and he became its leader."],["Death","After disputes within the revolutionary movement, Bonifacio was executed in May 1897. He is remembered as the Father of the Philippine Revolution."]],r:["phrev","rizal"]},
{id:"commonwealth",t:"The Philippine Commonwealth",c:"Philippines",i:"🏛️",p:[["Transition","The Tydings–McDuffie Act of 1934 promised independence after a ten-year transition. The Commonwealth of the Philippines was inaugurated on 15 November 1935."],["Leadership","Manuel L. Quezon was elected the first president of the Commonwealth, and the government promoted a national language and social reforms."],["War and independence","World War II interrupted the transition, and the Philippines became fully independent on 4 July 1946."]],r:["independence","japocc"]},
{id:"sulu",t:"The Sultanate of Sulu",c:"Philippines",i:"🕌",p:[["Islam arrives","Islam reached the southern Philippines through traders from the 14th century. The Sultanate of Sulu is traditionally dated to 1405."],["A maritime power","From its capital at Jolo, the sultanate controlled trade across the Sulu Sea and traded with China and Southeast Asia."],["Colonial era","Spain and later the United States struggled for centuries to bring Sulu under control, and its sultans kept considerable independence until the early 1900s."]],r:["mindanao","spanph"]},
{id:"phsport",t:"Sports in the Philippines",c:"Philippines",i:"🏀",p:[["Basketball","Basketball is the most popular sport, and the Philippine Basketball Association, founded in 1975, is the oldest professional league in Asia."],["Boxing","Manny Pacquiao became the first boxer to win world titles in eight weight divisions."],["Olympic gold","Hidilyn Diaz won the Philippines’ first Olympic gold medal, in weightlifting at the Tokyo Games in 2021."]],r:["ph","manila"]},
{id:"phdance",t:"Philippine Music and Dance",c:"Philippines",i:"💃",p:[["Folk dance","Tinikling, in which dancers step between clapping bamboo poles, is said to imitate the movement of the tikling bird."],["Songs","The kundiman is a traditional love song, and Original Pilipino Music, or OPM, covers popular music written and sung by Filipino artists."],["Instruments","Rondalla ensembles of guitars and bandurrias reflect Spanish influence, while kulintang gong ensembles come from the southern islands."]],r:["phfest","phlang"]},
{id:"jeepney",t:"The Jeepney",c:"Philippines",i:"🚌",p:[["Origins","Jeepneys began after World War II, when Filipinos converted surplus American military jeeps into passenger vehicles."],["Culture","Their bright paint, chrome and slogans made them a symbol of Filipino creativity and an icon of Philippine streets."],["Modernization","A public transport modernization program launched in 2017 aims to replace old diesel jeepneys with newer, cleaner vehicles."]],r:["manila","rail"]},
{id:"pulag",t:"Mount Pulag",c:"Philippines",i:"⛰️",p:[["Height","Mount Pulag, on the border of Benguet, Ifugao and Nueva Vizcaya, rises to 2,922 m and is the highest mountain on Luzon."],["Sea of clouds","Hikers often wake before dawn to watch the sun rise over a sea of clouds that fills the valleys below."],["Culture and wildlife","The mountain is sacred to the Ibaloi and Kankanaey peoples, and its mossy forests and grasslands shelter rare plants and the Philippine deer."]],r:["banaue","phbio"]}]);
