/* data/extra-sections5.js */
window.EXTRA=Object.assign(window.EXTRA||{},{
tides:[["Tides and life","Shores that are covered and uncovered twice a day host specialized life such as barnacles and crabs. Tidal power stations, such as La Rance in France, which opened in 1966, generate electricity from the flow."]],
microbe:[["Useful microbes","Yeast and bacteria make bread, cheese and yogurt, and soil microbes recycle nutrients. Gut bacteria help digest food and train the immune system."]],
moon:[["Craters and plains","The dark plains called maria are ancient lava flows. Craters record billions of years of impacts because the Moon has no weather to erase them."]],
viking:[["Trade and settlement","Norse traders traveled along Russian rivers to Constantinople and Baghdad, while settlers colonized Iceland and Greenland and ruled parts of England and Normandy."]],
reform:[["Beyond Luther","John Calvin led reform in Geneva, and Henry VIII broke with Rome in the 1530s, creating the Church of England. The Catholic Church answered with its own Counter-Reformation."]],
mesop:[["Science","Babylonian astronomers tracked the planets, and Mesopotamian mathematicians used a base-60 system that survives in 60-minute hours and 360-degree circles."]],
madag:[["Threats","Most of Madagascar’s original forest has been cleared for farming and fuel, putting many species at risk. Conservation parks and community projects aim to protect what remains."]],
rift:[["Lakes","Rift lakes such as Tanganyika, about 1,470 m deep, are among the deepest in the world, and Lake Victoria lies between two arms of the rift."]],
mekong:[["Fishing and dams","The Mekong supports one of the world’s largest inland fisheries. Dams on the river have raised concerns about fish migration and the sediment that feeds the delta."]],
camera:[["Inside a camera","A lens focuses light onto film or a sensor, while the aperture and shutter control how much light arrives. A digital sensor turns light into electrical signals pixel by pixel."]],
ev:[["Range and charging","Range depends on battery size, speed and temperature. Fast chargers can add a large share of a battery’s range in under an hour."]],
wind:[["Offshore wind","Offshore turbines catch stronger, steadier winds but cost more to build and maintain. The North Sea off Britain, Denmark, Germany and the Netherlands is home to the largest offshore wind farms, and China now builds the most."]],
manila:[["Landmarks","Rizal Park, Fort Santiago and Manila Cathedral are among the city’s landmarks, and San Agustin Church in Intramuros is part of a UNESCO World Heritage site."]],
spanph:[["Baroque churches","Four churches, in Manila, Paoay, Santa Maria and Miagao, make up the UNESCO site Baroque Churches of the Philippines, listed in 1993."]],
japocc:[["Resistance","Guerrilla groups, including the Hukbalahap, attacked Japanese forces and supplied intelligence to the Allies throughout the occupation."]],
edsa:[["Aftermath","Corazon Aquino became the first woman president of the Philippines. A second uprising on EDSA in 2001 later removed President Joseph Estrada."]],
phlang:[["Everyday speech","Many Filipinos mix English and Tagalog in speech, a style called Taglish, and Spanish loanwords such as mesa and silya are everyday vocabulary."]],
phbio:[["Threats","Deforestation, hunting and development threaten many species. The Philippine eagle is critically endangered, with only a few hundred pairs thought to remain."]],
banaue:[["Heritage at risk","Migration to cities, an aging farming population and landslides after typhoons have left some terraces abandoned, and community and government programs work to restore them."]],
phtyph:[["Preparedness","Early warnings, evacuation centers and community drills help reduce deaths. In Haiyan, storm surge rather than wind was the main killer."]],
phfood:[["Street food","Popular snacks include isaw (grilled chicken intestines), fish balls, kwek-kwek (battered quail eggs) and banana-cue. Meals often end with kakanin, or rice cakes."]],
rizal:[["Legacy","Rizal’s birthday and death anniversary are national observances, and monuments to him stand in towns across the country. The Rizal Law of 1956 requires students to study his life and works."]],
phpower:[["Challenges","The Philippines has had some of the higher electricity prices in Southeast Asia, and its island grids are exposed to typhoons and need new transmission links."]]});

;
/* data/extra-sections6.js */
window.EXTRA=Object.assign(window.EXTRA||{},{
cebu:[["Food and crafts","Cebu is famous for lechon, which many Filipinos rank as the best in the country, and for dried mangoes. Mactan Island is known for hand-made guitars."]],
mindanao:[["Wildlife and peoples","The Philippine eagle lives in the forests around Davao and elsewhere on the island. Indigenous Lumad peoples and the Maranao of Lake Lanao are among the island’s many cultures."]],
palawan:[["Conservation","UNESCO recognized Palawan as a biosphere reserve in 1990, and protected areas cover much of the island, though mining and tourism put pressure on them."]],
bohol:[["Heritage sights","Baclayon Church is one of the oldest stone churches in the country, and a monument recalls the 1565 blood compact between the Bohol chieftain Sikatuna and Legazpi."]],
taal:[["Tourism and risk","The view from Tagaytay Ridge made Taal a popular attraction, though the volcano island itself has been off limits since the 2020 eruption."]],
mayon:[["Safety zone","A permanent danger zone surrounds the cone, and thousands of residents are evacuated when alert levels rise. Albay is known for its disaster preparedness."]],
malolos:[["Barasoain Church","Barasoain Church in Malolos hosted the congress that drafted the 1899 constitution and is now a national shrine."]],
independence:[["Flag and anthem","The flag was sewn in Hong Kong by Marcela Agoncillo and others, and Julian Felipe composed the music of the national anthem in 1898."]],
phfest:[["MassKara","The MassKara festival in Bacolod began in 1980, with smiling masks meant to lift the spirits of a city facing hard times."]],
phfolk:[["Gods and guardians","Bathala is the supreme god in Tagalog belief, and Maria Makiling is said to guard the forests of Mount Makiling in Laguna."]],
phecon:[["Challenges","Rapid growth has come alongside persistent inequality and a large informal sector, and the country is working to attract more manufacturing and infrastructure investment."]],
baguio:[["Parks and markets","Burnham Park, named for the architect, is the city’s central green space and has a lake for boating, while Session Road is its main shopping street."]],
vigan:[["Food","Vigan empanada is a crisp orange pastry filled with papaya, egg and longganisa, and is a popular local snack."]],
boracay:[["Seasons","The best time to visit is the dry season from about November to May. Beaches on opposite sides of the island take turns being calm as the seasonal winds shift."]],
siargao:[["Island hopping","Nearby islets such as Naked, Daku and Guyam are popular for island hopping, and Sugba Lagoon offers kayaking and swimming."]],
pinatubo:[["Aftermath","The Aeta people who lived on Pinatubo’s slopes were displaced by the eruption. A crater lake formed afterward and can be reached by trekking through ash-covered valleys."]],
lapulapu:[["Monuments","A large bronze statue of Lapulapu stands in Mactan, and the Mactan Shrine marks the traditional site of the battle."]],
bonifacio:[["Monuments","The Bonifacio Monument in Caloocan, inaugurated in 1933, shows Katipunan fighters, and Bonifacio Day is observed on 30 November."]],
commonwealth:[["Language and women’s vote","In 1937 Filipino women won the right to vote in a plebiscite, and Tagalog was chosen as the basis of a national language."]],
sulu:[["Pearls and the Tausug","Sulu was known for its pearls. The Tausug are the main ethnic group, and they are known for the pangalay dance and for trade with Borneo."]],
phsport:[["Other sports","Billiards champion Efren Reyes is a national hero of the sport, and arnis, a martial art using sticks, was declared the national sport in 2009."]],
phdance:[["Pandanggo sa Ilaw","In this dance from Mindoro, performers balance oil lamps on their heads and the backs of their hands while they step and spin."]],
jeepney:[["Design","Each jeepney is a custom job, with the body built by local shops, and a typical one seats around 16 to 20 passengers."]],
pulag:[["Trails","Common routes include the Ambangeg, Tawangan and Akiki trails, and Akiki, nicknamed the Killer Trail, is the most strenuous."]]});

;
/* data/articles-arts-health.js */
window.MORE=(window.MORE||[]).concat([
{id:"shakes",t:"William Shakespeare",c:"Arts and Literature",i:"🎭",p:[["Life","Shakespeare was born in Stratford-upon-Avon in 1564 and died there in 1616. He worked as an actor, playwright and part-owner of a theater company in London."],["Works","He wrote about 37 plays and 154 sonnets, including Hamlet, Macbeth, Romeo and Juliet and A Midsummer Night’s Dream."],["The Globe","His company’s Globe Theatre opened in 1599. His plays are now performed and translated around the world."]],r:["renais","print"]},
{id:"homer",t:"Homer and the Epics",c:"Arts and Literature",i:"📜",p:[["Two poems","The Iliad and the Odyssey are traditionally credited to Homer and were composed around the 8th century BCE."],["Stories","The Iliad tells of anger and death in the Trojan War, while the Odyssey follows Odysseus on his ten-year voyage home."],["Oral tradition","The poems grew out of oral tradition, in which singers recited long stories from memory using repeated phrases that helped them keep the verse."]],r:["greece","phfolk"]},
{id:"novel",t:"The Novel",c:"Arts and Literature",i:"📚",p:[["Early novels","Miguel de Cervantes’s Don Quixote, published in 1605 and 1615, is often called the first modern novel."],["The 1800s","The printing press and rising literacy fed a boom in the form, with writers such as Jane Austen, Charles Dickens and Leo Tolstoy."],["Novels and nations","Novels such as Uncle Tom’s Cabin and Things Fall Apart have changed how whole nations see themselves."]],r:["print","rizal"]},
{id:"impress",t:"Impressionism",c:"Arts and Literature",i:"🖼️",p:[["Name","The movement took its name from Claude Monet’s painting Impression, Sunrise (1872), after a critic mocked the group’s first exhibition in Paris in 1874."],["Painters","Monet, Pierre-Auguste Renoir, Edgar Degas and Camille Pissarro were among its leading figures."],["Style","They painted outdoors, captured changing light with loose, quick brushstrokes, and benefited from paint sold in tubes, invented in 1841."]],r:["light","camera"]},
{id:"musicw",t:"Western Classical Music",c:"Arts and Literature",i:"🎻",p:[["Periods","The Baroque period includes J. S. Bach (1685 to 1750), the Classical period includes Haydn and Mozart (1756 to 1791), and Beethoven (1770 to 1827) bridged to the Romantic era."],["The orchestra","A symphony orchestra has strings, woodwinds, brass and percussion, led by a conductor."],["The piano","Bartolomeo Cristofori built the first piano in Italy around 1700, and it became the main keyboard instrument of the 1800s."]],r:["sound","renais"]},
{id:"cinema",t:"The Birth of Cinema",c:"Arts and Literature",i:"🎬",p:[["First screenings","The Lumière brothers gave the first public paid film screening in Paris on 28 December 1895, after earlier work by Thomas Edison’s team."],["Sound and color","The Jazz Singer, released in 1927, popularized talking pictures, and Technicolor brought lasting color to the screen."],["Industries","Hollywood became the center of the American film industry, and India’s Bollywood and film industries elsewhere also grew into major producers."]],r:["camera","light"]},
{id:"heart",t:"The Human Heart",c:"Health and the Body",i:"❤️",p:[["Structure","The heart is about the size of a fist and has four chambers. The right side sends blood to the lungs and the left side sends it around the body."],["Circulation","William Harvey described the circulation of the blood in 1628. Arteries carry blood away from the heart and veins carry it back."],["Rhythm","An adult heart beats around 60 to 100 times a minute at rest, driven by a natural pacemaker made of specialized cells."]],r:["cell","brain"]},
{id:"lungs",t:"Lungs and Breathing",c:"Health and the Body",i:"🫁",p:[["Gas exchange","Air travels down the windpipe into branching tubes that end in tiny air sacs called alveoli, where oxygen enters the blood and carbon dioxide leaves it."],["The diaphragm","A dome-shaped muscle under the lungs, the diaphragm, contracts to draw air in and relaxes to push it out."],["Care","Smoking is a leading cause of lung disease, and clean air and exercise help keep the lungs healthy."]],r:["photo","heart"]},
{id:"digest",t:"Digestion",c:"Health and the Body",i:"🍽️",p:[["The route","Food passes from the mouth through the esophagus to the stomach, where acid and enzymes break it down, and then into the small intestine."],["Absorption","The small intestine, about 6 meters long, absorbs most nutrients into the blood, while the large intestine absorbs water."],["Gut bacteria","Trillions of bacteria in the gut help digest food and make some vitamins."]],r:["microbe","nutri"]},
{id:"bones",t:"Bones and Muscles",c:"Health and the Body",i:"🦴",p:[["The skeleton","An adult has 206 bones, which support the body, protect organs and store minerals such as calcium."],["Muscles","The body has more than 600 muscles. Tendons attach them to bones, and muscles pull by contracting."],["Growth","Babies are born with about 300 bones, and many of them fuse together as children grow."]],r:["cell","heart","muscles"]},
{id:"sleep",t:"Sleep",c:"Health and the Body",i:"😴",p:[["Needs","Most adults need about 7 to 9 hours of sleep a night, and children and teenagers need more."],["Stages","Sleep moves through cycles of about 90 minutes, from light sleep to deep sleep and rapid eye movement (REM) sleep, when most vivid dreams occur."],["Why it matters","Sleep helps the brain consolidate memories and the body repair itself, and poor sleep is linked to health problems."]],r:["brain","heart"]},
{id:"nutri",t:"Nutrition",c:"Health and the Body",i:"🥦",p:[["Nutrients","The body needs carbohydrates, proteins and fats in large amounts, plus vitamins, minerals and water."],["Scurvy","In 1747 James Lind showed that citrus fruit cured scurvy, later traced to a lack of vitamin C."],["Balance","A varied diet with plenty of vegetables, fruit and fiber supports health, and needs vary with age and activity."]],r:["digest","bones"]}]);
