/* data/articles-arts-health2.js */
window.MORE=(window.MORE||[]).concat([
{id:"davinci",t:"Leonardo da Vinci",c:"Arts and Literature",i:"🎨",p:[["Life","Leonardo was born in 1452 near Vinci in Tuscany and died in France in 1519. He worked as a painter, engineer, anatomist and inventor."],["Paintings","The Mona Lisa and The Last Supper, painted in the 1490s, are among the most famous artworks in the world."],["Notebooks","About 7,000 pages of his notebooks survive, filled with sketches of anatomy, machines and flight, written in mirror script."]],r:["renais","bones"]},
{id:"gothic",t:"Gothic Architecture",c:"Arts and Literature",i:"⛪",p:[["Origins","Gothic architecture began in France in the 12th century, with the abbey church of Saint-Denis near Paris as an early example."],["Features","Pointed arches, ribbed vaults and flying buttresses let builders raise tall walls with large stained-glass windows."],["Cathedrals","Notre-Dame de Paris was begun in 1163, and its roof and spire were badly damaged by fire on 15 April 2019. Chartres and Cologne are also great Gothic cathedrals."]],r:["renais","rome"]},
{id:"jazz",t:"Jazz",c:"Arts and Literature",i:"🎷",p:[["Origins","Jazz emerged in New Orleans in the early 1900s, drawing on blues, ragtime and African American musical traditions."],["Style","Improvisation and swing rhythm define the music, and artists such as Louis Armstrong, Duke Ellington and Ella Fitzgerald shaped its sound."],["Spread","Bebop arrived in the 1940s, and later players such as Miles Davis and John Coltrane kept pushing the style in new directions."]],r:["musicw","sound"]},
{id:"austen",t:"Jane Austen",c:"Arts and Literature",i:"✍️",p:[["Life","Jane Austen lived from 1775 to 1817 in the English countryside, and wrote about the lives of the gentry."],["Novels","Sense and Sensibility appeared in 1811, Pride and Prejudice in 1813 and Emma in 1815."],["Reputation","Her books were published anonymously during her lifetime, and she is now regarded as one of the great English novelists."]],r:["novel","shakes"]},
{id:"theatre",t:"Ancient Greek Theatre",c:"Arts and Literature",i:"🎭",p:[["Origins","Greek drama grew out of festivals honoring the god Dionysus in Athens in the 6th and 5th centuries BCE."],["Playwrights","Aeschylus, Sophocles and Euripides wrote the great tragedies, while Aristophanes wrote comedies."],["Theaters","Open-air theaters such as Epidaurus, which seats about 14,000 people, had remarkable acoustics and are still used for performances."]],r:["greece","shakes"]},
{id:"phlit",t:"Philippine Literature",c:"Arts and Literature",i:"📕",p:[["Oral roots","Before colonization, epics, proverbs and riddles were passed on orally in many languages."],["Colonial era","Francisco Balagtas wrote the Tagalog epic poem Florante at Laura in the 1830s, and José Rizal’s novels of the 1880s and 1890s inspired the independence movement."],["Modern writing","Filipino writers work in Filipino, English and regional languages, and the National Artist award honors figures such as Nick Joaquin."]],r:["rizal","phlang"]},
{id:"eye",t:"The Eye and Vision",c:"Health and the Body",i:"👁️",p:[["How we see","Light passes through the cornea and lens and is focused onto the retina, which sends signals along the optic nerve to the brain."],["Cells","The retina holds roughly 120 million rods, which work in dim light, and about 6 million cones, which detect color."],["Eye care","Reading in good light, wearing sunglasses and getting regular checkups help protect vision, and glasses correct common focusing problems."]],r:["light","brain"]},
{id:"blood",t:"Blood",c:"Health and the Body",i:"🩸",p:[["Components","Blood is made of plasma and cells. Red cells carry oxygen using hemoglobin, white cells fight infection and platelets help blood clot."],["Amount","An adult has about 5 liters of blood, which the heart pumps around the body."],["Blood types","Karl Landsteiner discovered the ABO blood groups in 1901, which made safe blood transfusions possible."]],r:["heart","immune"]},
{id:"skin",t:"The Skin",c:"Health and the Body",i:"🧴",p:[["Layers","Skin is the body’s largest organ. The outer epidermis forms a waterproof barrier, and the dermis below contains nerves, blood vessels and sweat glands."],["Functions","It protects against germs, helps control temperature through sweating and senses touch, heat and pain."],["Sun and renewal","Melanin gives skin color and some protection from ultraviolet light, and the outer layer renews itself roughly every month."]],r:["cell","nutri"]},
{id:"vacc",t:"Vaccines and Public Health",c:"Health and the Body",i:"💉",p:[["First vaccines","Edward Jenner’s smallpox vaccine of 1796 launched vaccination, and smallpox was declared eradicated in 1980."],["Herd immunity","When enough people are immune, a disease finds it hard to spread, which protects people who cannot be vaccinated."],["Public health","Clean water, sanitation and vaccination programs have greatly cut deaths from infectious diseases, and the World Health Organization was founded in 1948 to coordinate global health."]],r:["immune","microbe"]},
{id:"exercise",t:"Exercise",c:"Health and the Body",i:"🏃",p:[["Guidelines","Health agencies suggest that adults get at least 150 minutes of moderate activity a week, such as brisk walking."],["Benefits","Regular exercise strengthens the heart, muscles and bones, helps control weight and improves mood and sleep."],["Types","Aerobic exercise builds endurance, strength training builds muscle, and stretching helps flexibility."]],r:["heart","bones"]},
{id:"ear",t:"Hearing and the Ear",c:"Health and the Body",i:"👂",p:[["Parts","The outer ear collects sound, the middle ear’s three tiny bones pass vibrations along, and the cochlea in the inner ear turns them into nerve signals."],["Balance","Fluid-filled semicircular canals in the inner ear help the body keep its balance."],["Protecting hearing","Loud noise can permanently damage the delicate hair cells in the cochlea, so earplugs and lower volume help prevent hearing loss."]],r:["sound","brain"]}]);
