window.EXTRA=Object.assign(window.EXTRA||{},{
gmyth:[["The underworld","Hades ruled the underworld, and the myth of Persephone’s abduction explained the changing seasons."]],
opera:[["Opera houses","La Scala in Milan, opened in 1778, and the Sydney Opera House, opened in 1973, are among the world’s most famous opera venues."]],
haikuart:[["Modern haiku","Masaoka Shiki revived the form in the late 1800s and gave it the name haiku. Poets now write haiku in many languages."]],
teeth:[["Baby teeth","Children have 20 baby teeth, which fall out and are replaced by permanent teeth between about ages 6 and 12."]],
water:[["Dehydration","Even mild dehydration can cause headaches and tiredness, since the body loses water through sweat, breath and urine."]],
flu:[["Changing strains","Flu viruses mutate quickly, so health agencies update the vaccine each year to match the strains in circulation."]],
zero:[["Other placeholders","The Maya and the Babylonians each used a symbol for zero as a placeholder in their number systems."]],
euclid:[["Beyond Euclid","In the 1800s mathematicians including Gauss, Bolyai and Lobachevsky found geometries in which Euclid’s parallel postulate fails, and Einstein later used curved geometry to describe gravity."]],
prob:[["Large numbers","The more times a fair coin is tossed, the closer the share of heads gets to one half, an idea known as the law of large numbers."]],
prime:[["Twin primes","Pairs of primes that differ by 2, such as 11 and 13, are called twin primes, and no one has yet proved whether there are infinitely many."]],
socr:[["The Socratic method","The Socratic method teaches by asking a chain of questions, and it is still used in law schools today."]],
buddh:[["Meditation","Meditation is a central practice, and monks and nuns in Buddhist monasteries follow rules of conduct."]],
confu:[["Civil service","Confucian ideas helped shape the imperial examination system, which selected officials by merit in China for over a thousand years."]],
relig:[["Non-religious","Roughly one in six people worldwide say they have no religious affiliation."]],
penguin:[["Sizes","The little penguin stands only about 33 cm tall, while king penguins breed in colonies of hundreds of thousands."]],
octopus:[["Giant octopus","The giant Pacific octopus can span several meters from arm tip to arm tip and weigh tens of kilograms."]],
wolf:[["Communication","Wolves communicate with howls, body language and scent marks."]],
frog:[["Poison dart frogs","Brightly colored poison dart frogs of Central and South America carry toxins in their skin as a warning to predators."]],
tiger:[["Subspecies","Subspecies include the Bengal, Siberian and Sumatran tigers, and the Sumatran is the smallest living one."]],
bat:[["Vampire bats","Only three species of bats feed on blood, and all of them live in Latin America."]],
jupiter:[["Rings and radiation","Jupiter has faint rings, a powerful magnetic field and intense radiation belts."]],
saturn:[["Tilt and seasons","Saturn is tilted about 27 degrees, so its rings open and narrow as it moves around its roughly 29-year orbit."]],
milky:[["Seeing it","From a dark site the Milky Way appears as a faint band of light across the sky, because we look edge-on through its disk."]],
iss:[["Life on board","Astronauts exercise for about two hours a day to protect their muscles and bones in weightlessness."]],
eclipse:[["Eclipse safety","Looking at the Sun without proper eclipse glasses can permanently damage the eyes, except during the brief totality of a total solar eclipse."]],
pulsar:[["Magnetars","Magnetars are neutron stars with extremely powerful magnetic fields."]],
supdem:[["Shifting curves","A change in income, taste or technology can shift demand or supply and move the market price."]],
money:[["Digital money","Most money today exists as bank balances on computers, and cards and payment apps move it electronically."]],
trade:[["Tariffs","Tariffs, which are taxes on imports, can protect local industries but raise prices for consumers."]],
rice:[["Varieties","Rice comes in thousands of varieties, from fragrant jasmine and basmati to the short, sticky rice used in Japanese sushi and Asian desserts."]],
agri:[["Domestication","Early farmers chose the best plants and animals over generations, gradually changing wild species into crops and livestock."]],
coffee:[["Growers","Most coffee is grown by small farmers in tropical countries, and fair trade programs aim to pay them more stable prices."]],
inflation:[["Interest rates","Central banks fight inflation by raising interest rates, which slows borrowing and spending."]],
gdp:[["Growth","A rise in real GDP, adjusted for inflation, is called economic growth."]],
stockm:[["Bulls and bears","A rising market is called a bull market and a falling one a bear market."]],
insur:[["Reinsurance","Insurers buy their own insurance, called reinsurance, to protect themselves against huge losses such as major catastrophes."]],
urban:[["Planning","Compact planning, public transit and green spaces can make cities more livable and cut energy use."]],
wheat:[["Types","Hard wheat is used for bread, soft wheat for cakes and pastries, and durum wheat for pasta."]],
spice:[["Pepper","Black pepper, native to India, was once so valuable that it was used to pay rent and taxes."]],
choco:[["Cocoa farming","Cacao trees grow only near the equator and take years to bear fruit, and each pod holds 20 to 60 beans."]],
fish:[["Great fishing nations","China, Indonesia, India, Peru, Russia and the United States catch the most fish, and millions of people depend on fishing for a living."]],
potato:[["Uses","Potatoes are boiled, baked and fried, and are also used to make starch and vodka."]]});

;
