window.MORE=(window.MORE||[]).concat([
{id:"mozart",t:"Wolfgang Amadeus Mozart",c:"Music",i:"🎹",p:[["Prodigy","Mozart was born in Salzburg in 1756 and toured Europe as a child prodigy, playing keyboard and violin before royal courts."],["Works","He composed more than 600 works, including the operas The Marriage of Figaro (1786), Don Giovanni (1787) and The Magic Flute (1791)."],["Death","He died in Vienna in 1791 at the age of 35, leaving his Requiem unfinished."]],r:["musicw","opera"]},
{id:"opm",t:"Original Pilipino Music",c:"Music",i:"🇵🇭",p:[["OPM","Original Pilipino Music, or OPM, covers popular songs written and performed by Filipino artists in Filipino, English and regional languages."],["Milestones","The Apo Hiking Society formed in 1969, Freddie Aguilar’s Anak became a worldwide hit in the late 1970s, and the Eraserheads led the Pinoy rock boom of the 1990s."],["Stage and screen","Lea Salonga won an Olivier Award in 1990 for Miss Saigon on the London stage, and Filipino singers are known worldwide."]],r:["phdance","guitar"]},
{id:"blues",t:"The Blues",c:"Music",i:"🎷",p:[["Origins","The blues grew in the Mississippi Delta around the turn of the 20th century from spirituals, work songs and field hollers."],["Form","Many blues songs use a twelve-bar pattern. W. C. Handy published Memphis Blues in 1912, and artists such as Robert Johnson and B. B. King shaped the genre."],["Influence","The blues helped give rise to jazz, rhythm and blues and rock and roll."]],r:["jazz","beatles"]},
{id:"electro",t:"Electronic Music",c:"Music",i:"🎛️",p:[["Synthesizers","Robert Moog introduced his modular synthesizer in the 1960s, and German group Kraftwerk built a sound around electronics in the 1970s."],["Dance music","House music emerged in Chicago in the early 1980s and techno in Detroit in the mid-1980s."],["Today","Producers can now make full tracks on a laptop, and electronic sounds are everywhere in pop, film and games."]],r:["sound","chip"]},
{id:"reggae",t:"Reggae",c:"Music",i:"🌴",p:[["Jamaica","Reggae developed in Jamaica in the late 1960s from ska and rocksteady, with a slow groove and offbeat guitar."],["Bob Marley","Bob Marley and the Wailers brought it worldwide, and albums such as Exodus (1977) spread messages of peace and unity."],["Culture","The music is linked with Rastafari, and UNESCO added reggae to its list of intangible cultural heritage in 2018."]],r:["jazz","blues"]},
{id:"tennis",t:"Tennis",c:"Sports",i:"🎾",p:[["Origins","Walter Clopton Wingfield patented a game he called lawn tennis in 1874, and the first Wimbledon Championship was held in 1877."],["Grand Slams","The four major tournaments are the Australian Open, the French Open, Wimbledon and the US Open."],["Stars","Players such as Rafael Nadal, Roger Federer and Novak Djokovic dominated men’s tennis for two decades, while Serena Williams and others shaped the women’s game."]],r:["olymp","soccer"]},
{id:"athletics",t:"Athletics",c:"Sports",i:"🏃",p:[["Events","Athletics, or track and field, includes sprints, distance races, jumps and throws, and has been central to the Olympics since ancient times."],["Marathon","The marathon recalls the legend of the messenger Pheidippides. Its distance, 42.195 km, was standardized in 1921 after the 1908 London Olympics."],["Records","Usain Bolt of Jamaica set the 100 m world record of 9.58 seconds in 2009."]],r:["olymp","greece"]},
{id:"swimming",t:"Swimming",c:"Sports",i:"🏊",p:[["Strokes","Competitive swimming has four strokes: freestyle, backstroke, breaststroke and butterfly."],["Olympics","Swimming has been part of every modern Olympics since 1896."],["Phelps","Michael Phelps won 23 Olympic gold medals, more than any other athlete in history."]],r:["olymp","whale"]},
{id:"cricket",t:"Cricket",c:"Sports",i:"🏏",p:[["Origins","Cricket developed in England in the 1500s and 1600s, and the first official Test match was played between Australia and England in Melbourne in 1877."],["Formats","Test matches last up to five days, one-day internationals last a day and Twenty20, introduced in England in 2003, lasts about three hours."],["Reach","The sport is hugely popular in India, Pakistan, Australia, England and the Caribbean."]],r:["olymp","soccer"]},
{id:"martial",t:"Martial Arts and Boxing",c:"Sports",i:"🥋",p:[["Eastern traditions","Jigoro Kano founded judo in Japan in 1882, karate developed in Okinawa and taekwondo comes from Korea."],["Fighting arts of the world","Martial arts include many traditions: capoeira from Brazil, krav maga from Israel, Muay Thai from Thailand, sambo from Russia and kung fu from China. Some are practiced as sports, some for self-defense and some for fitness or spiritual growth."],["Boxing","Boxing has a long Olympic history, and champions such as Muhammad Ali became global figures."]],r:["phsport","olymp"]},
{id:"spanish",t:"The Spanish Language",c:"Languages",i:"🇪🇸",p:[["Origins","Spanish evolved from the Latin spoken in the Iberian Peninsula and spread through the Spanish empire."],["Today","About 500 million people speak Spanish as a first language, making it second only to Mandarin, and it is official in about twenty countries."],["Around the world","Spanish is an official language in 20 countries, and Mexico has the most speakers."]],r:["spanph","langevo"]},
{id:"mandarin",t:"Mandarin Chinese",c:"Languages",i:"🇨🇳",p:[["Speakers","Mandarin has more native speakers than any other language, roughly 900 million."],["Tones","It is a tonal language with four main tones, so the same syllable can have different meanings depending on pitch."],["Writing","Chinese is written with characters, and pinyin, a system of Latin letters that spells out Mandarin sounds, was introduced in 1958."]],r:["china","alphabet"]},
{id:"latin",t:"Latin",c:"Languages",i:"🏛️",p:[["Language of Rome","Latin was the language of ancient Rome, and it spread across Europe with the empire."],["Descendants","Spanish, French, Italian, Portuguese and Romanian descend from Latin and are called Romance languages."],["Still used","Latin remains in law, religion and science, and Carl Linnaeus’s system of Latin names for species dates from the 1750s."]],r:["rome","spanish"]},
{id:"arabic",t:"Arabic",c:"Languages",i:"📜",p:[["Script","Arabic is a Semitic language written from right to left in a cursive script."],["Forms","The Quran was revealed in Classical Arabic, Modern Standard Arabic is used in media and education, and spoken dialects differ across countries."],["Loanwords","English words such as algebra, algorithm, coffee and sugar came from Arabic."]],r:["islam","alphabet"]},
{id:"signlang",t:"Sign Languages",c:"Languages",i:"🤟",p:[["Real languages","Sign languages are full languages with their own grammar, and they are not universal: American, British and Japanese Sign Language all differ."],["History","The first permanent school for deaf students in the United States, founded in Hartford in 1817 by Thomas Gallaudet and Laurent Clerc, helped create American Sign Language."],["Official recognition","More than seventy countries have recognized a national sign language in law, and the UN Convention on the Rights of Persons with Disabilities of 2006 recognizes sign languages as languages."]],r:["phlang","ear"]}]);
